using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using StudentAccommodationSystem.Data; using Microsoft.AspNetCore.Hosting; using StudentAccommodationSystem.Models; using StudentAccommodationSystem.ViewModels;
namespace StudentAccommodationSystem.Controllers;
public class PropertyController(ApplicationDbContext db,UserManager<ApplicationUser> users,IWebHostEnvironment env):Controller
{
 public async Task<IActionResult> Index(PropertySearchVm m){var q=db.Properties.Include(p=>p.Rooms).Include(p=>p.Images).Where(p=>p.Status=="Approved").AsQueryable();if(!string.IsNullOrWhiteSpace(m.Location))q=q.Where(p=>p.City.Contains(m.Location)||p.State.Contains(m.Location));if(!string.IsNullOrWhiteSpace(m.Name))q=q.Where(p=>p.Name.Contains(m.Name));if(m.MinRent.HasValue)q=q.Where(p=>p.Rooms.Any(r=>r.MonthlyRent>=m.MinRent));if(m.MaxRent.HasValue)q=q.Where(p=>p.Rooms.Any(r=>r.MonthlyRent<=m.MaxRent));if(!string.IsNullOrWhiteSpace(m.RoomType))q=q.Where(p=>p.Rooms.Any(r=>r.RoomType==m.RoomType));if(m.Furnished.HasValue)q=q.Where(p=>p.Rooms.Any(r=>r.IsFurnished==m.Furnished));m.Results=await q.OrderByDescending(p=>p.CreatedAt).ToListAsync();return View(m);}
 public async Task<IActionResult> Details(int id){var p=await db.Properties.Include(x=>x.Rooms).Include(x=>x.Images).Include(x=>x.Reviews).FirstOrDefaultAsync(x=>x.Id==id);return p==null?NotFound():View(p);}
 private async Task SavePropertyImagesAsync(int propertyId,List<IFormFile> images){var webRoot = env.WebRootPath ?? Path.Combine(env.ContentRootPath, "wwwroot");Directory.CreateDirectory(webRoot);var dir=Path.Combine(webRoot,"uploads","properties",propertyId.ToString());Directory.CreateDirectory(dir);var hasPrimary=await db.PropertyImages.AnyAsync(x=>x.PropertyId==propertyId);foreach(var file in images.Where(x=>x.Length>0).Take(12)){if(file.Length>5*1024*1024)continue;var ext=Path.GetExtension(file.FileName).ToLowerInvariant();if(ext is not ".jpg" and not ".jpeg" and not ".png" and not ".webp")continue;var name=$"{Guid.NewGuid():N}{ext}";await using var stream=new FileStream(Path.Combine(dir,name),FileMode.Create);await file.CopyToAsync(stream);db.PropertyImages.Add(new PropertyImage{PropertyId=propertyId,ImageUrl=$"/uploads/properties/{propertyId}/{name}",IsPrimary=!hasPrimary});hasPrimary=true;}await db.SaveChangesAsync();}

 [HttpPost,Authorize(Roles="Owner,Administrator"),ValidateAntiForgeryToken]
 public async Task<IActionResult> UploadImages(int propertyId,List<IFormFile> images){var p=await db.Properties.Include(x=>x.Images).Include(x=>x.Owner).FirstOrDefaultAsync(x=>x.Id==propertyId);if(p==null)return NotFound();var u=await users.GetUserAsync(User);if(User.IsInRole("Owner") && (u==null || p.Owner.UserId!=u.Id))return Forbid();var webRoot = env.WebRootPath ?? Path.Combine(env.ContentRootPath, "wwwroot");Directory.CreateDirectory(webRoot);var dir=Path.Combine(webRoot,"uploads","properties",propertyId.ToString());Directory.CreateDirectory(dir);foreach(var file in images.Where(x=>x.Length>0).Take(12)){if(file.Length>5*1024*1024)continue;var ext=Path.GetExtension(file.FileName).ToLowerInvariant();if(ext is not ".jpg" and not ".jpeg" and not ".png" and not ".webp")continue;var name=$"{Guid.NewGuid():N}{ext}";var path=Path.Combine(dir,name);await using var stream=new FileStream(path,FileMode.Create);await file.CopyToAsync(stream);db.PropertyImages.Add(new PropertyImage{PropertyId=propertyId,ImageUrl=$"/uploads/properties/{propertyId}/{name}",IsPrimary=!p.Images.Any() && !db.PropertyImages.Any(x=>x.PropertyId==propertyId)});}await db.SaveChangesAsync();return RedirectToAction(nameof(Details),new{id=propertyId});}

 [Authorize(Roles="Owner")] public IActionResult Create()=>View(new Property());
 [HttpPost,Authorize(Roles="Owner,Administrator"),ValidateAntiForgeryToken] public async Task<IActionResult> Create(Property p,List<IFormFile> images){if(!ModelState.IsValid)return View(p);var u=await users.GetUserAsync(User);var op=await db.OwnerProfiles.FirstAsync(x=>x.UserId==u!.Id);p.OwnerProfileId=op.Id;p.Status=User.IsInRole("Administrator")?"Approved":"Pending";db.Properties.Add(p);await db.SaveChangesAsync();if(images!=null && images.Count>0){await SavePropertyImagesAsync(p.Id,images);}return RedirectToAction(nameof(Details),new{id=p.Id});}
}
